'use client';
// app/page.tsx — 心の羅針盤(和紙 × 銅版画ボタニカル × 縦書きの余白)
// 注意: 既存の ATLAS 定数(base64画像)はそのまま残して使います。
// このファイルの「ここにATLASを貼る」の行に、今の page.tsx から ATLAS の定義行をコピーしてください。

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import dynamic from 'next/dynamic';

const CompassCircle = dynamic(
  () => import('./components/CompassCircle').then(mod => ({ default: mod.CompassCircle })),
  { ssr: false }
);
import Backdrop from './components/NightBackdrop';

// ▼▼▼ ここにATLASを貼る(今のpage.tsxから const ATLAS = "data:image/webp;base64,..." の行を丸ごと) ▼▼▼
const ATLAS = "data:image/webp;base64,";

// ▲▲▲ ---------------------------------------------------------------- ▲▲▲

type Daily = { content?: string; word?: string; advice?: string; moonPhase?: string };

export default function TodayPage() {
  const router = useRouter();
  const [visible, setVisible] = useState(false);
  const [daily, setDaily] = useState<Daily | null>(null);
  const [moon, setMoon] = useState<{ phase: string } | null>(null);

  const now = new Date();
  const dateStr = `${now.getFullYear()}年${now.getMonth() + 1}月${now.getDate()}日`;

  useEffect(() => {
    try {
      if (!localStorage.getItem('lunaria_intro_seen')) {
        router.push('/intro');
        return;
      }
    } catch {}

    setTimeout(() => setVisible(true), 300);

    (async () => {
      try {
        const { getMoonInfo } = await import('@/lib/astro');
        const info = getMoonInfo(new Date());
        setMoon({ phase: info.phase });
      } catch (e) { console.error(e); }

      try {
        const res = await fetch('/api/daily');
        const data = await res.json();
        if (!data.error) setDaily(data);
      } catch (e) { console.error(e); }
    })();
  }, [router]);

  // /api/daily の形が {content} でも {word, advice} でも表示できるように
  const dailyText = daily?.content ?? daily?.word ?? null;
  const dailySub = daily?.advice ?? null;

  return (
    <div className="today-page">
      <Backdrop />
      {/* 和紙の粒子
      <div className="washi-grain" aria-hidden />

      ボタニカル:右の頁の外から入ってくる。左は余白のまま
      {ATLAS && (
        <img src={ATLAS} alt="" aria-hidden className="atlas-flora"
          style={{ opacity: visible ? 0.5 : 0 }} />
      )} */}

      <div className="today-inner" style={{
        opacity: visible ? 1 : 0,
        transform: visible ? 'none' : 'translateY(12px)',
        transition: 'opacity 1.6s ease, transform 1.6s ease',
      }}>

        {/* 頭:銘と日付 */}
        <header className="today-header">
          <span className="today-brand">LUNARIA</span>
          <span className="today-date">
            {dateStr}{moon ? ` ・ ${moon.phase}` : ''}
          </span>
        </header>

        {/* 今日のエネルギー(共有リーディング) */}
        {dailyText && (
          <div className="today-daily" style={{
            opacity: visible ? 1 : 0,
            transition: 'opacity 2s ease 0.5s',
          }}>
            <p className="today-daily-text">{dailyText}</p>
            {dailySub && <p className="today-daily-sub">{dailySub}</p>}
          </div>
        )}

        {/* 本体:左に縦書きの問い、右に羅針盤 */}
        <div className="today-layout">
          <div className="tate">
            <h1>今日の心は、<br />どのあたり</h1>
          </div>

          <CompassCircle />
        </div>

      </div>
    </div>
  );
}